#!/bin/bash
# Task body for the per-organism solo-baseline training runs (one held-out
# organism trained alone, 5 seeds each). Portable: called by
# solo_train_array.sh (SLURM) and run_local.sh train_solo <n>.
#
# Requires: ROOT set, SLURM_ARRAY_TASK_ID is a 1-based line number into
# solo_tasks.txt (generated by generate_task_lists.sh).
set -euo pipefail

TASKS_FILE="$ROOT/solo_tasks.txt"
LINE=$(sed -n "${SLURM_ARRAY_TASK_ID}p" "$TASKS_FILE")
if [ -z "$LINE" ]; then
    echo "train_solo.sh: no line ${SLURM_ARRAY_TASK_ID} in $TASKS_FILE" >&2
    exit 1
fi
GRP=$(echo "$LINE" | cut -d, -f1)
ACC=$(echo "$LINE" | cut -d, -f2)
CSV=$(echo "$LINE" | cut -d, -f3)
SEED=$(echo "$LINE" | cut -d, -f4)
RUN_NAME="solo_${GRP}_${ACC}_seed${SEED}"

echo "[$(date +%T)] ${RUN_NAME} (csv=${CSV})"

uv run --project "$ROOT/ml" python3 "$ROOT/ml/main.py" train \
    --data_path "$ROOT/$CSV" \
    --ckpt_dir "$ROOT/results/checkpoints_solo" \
    --context_len 150 \
    --no_cov \
    --augment \
    --epochs 50 \
    --early_stop 10 \
    --seed "$SEED" \
    --device "$DEVICE" \
    --val_split 0.2 \
    --run_name "$RUN_NAME"

echo "[$(date +%T)] Koniec: ${RUN_NAME}"
